"""Импорт банковских выписок.

Поддерживаются CSV-выписки банков «Нова» и «Сфера»:

    date,amount,description                  (nova)
    2026-03-01,-350.00,Кофейня Зерно

    Дата;Сумма;Описание                      (sfera)
    01.03.2026;-1 200,50;Магазин Лента

    Дата;Описание;Приход;Расход              (sfera_split)
"""

from __future__ import annotations

import csv
import datetime as dt
import io
import logging
import os
import re
from collections import Counter
from dataclasses import dataclass, replace
from decimal import Decimal

from ledger.clock import Clock, SystemClock
from ledger.errors import (
    StatementError,
    StatementRowError,
    UnknownFormatError,
    ValidationError,
)
from ledger.models import Transaction, parse_amount, to_money
from ledger.rules import Categorizer, normalize_text
from ledger.storage import MemoryStore

logger = logging.getLogger(__name__)

NOVA_COLUMNS = ("date", "amount", "description")

# формат -> (разделитель, обязательные колонки в нижнем регистре)
_FORMATS: dict[str, tuple[str, tuple[str, ...]]] = {
    "nova": (",", NOVA_COLUMNS),
    "sfera": (";", ("дата", "сумма", "описание")),
    "sfera_split": (";", ("дата", "описание", "приход", "расход")),
}
_DETECT_ORDER = ("nova", "sfera", "sfera_split")

_SEP = "[   ]"
_SFERA_AMOUNT = re.compile(rf"([+-]?)([0-9]+|[0-9]{{1,3}}(?:{_SEP}[0-9]{{3}})+)(?:,([0-9]+))?")
_SFERA_DATE = re.compile(r"([0-9]{2})\.([0-9]{2})\.([0-9]{4})")


@dataclass(frozen=True)
class RowError:
    line_no: int
    message: str


@dataclass(frozen=True)
class ImportResult:
    format: str
    encoding: str
    added: int
    duplicates: int
    errors: list[RowError]


def normalize_description(text: str) -> str:
    """Вид описания для сравнения (то же, что везде в проекте)."""
    return normalize_text(text)


def _read_text(path: str | os.PathLike[str]) -> tuple[str, str]:
    with open(path, "rb") as fh:
        raw = fh.read()
    try:
        return raw.decode("utf-8-sig"), "utf-8"
    except UnicodeDecodeError:
        pass
    try:
        return raw.decode("cp1251"), "cp1251"
    except UnicodeDecodeError as exc:
        raise StatementError(f"cannot decode file: {exc}") from exc


def _reader(text: str, delimiter: str):
    return csv.reader(io.StringIO(text, newline=""), delimiter=delimiter)


def _header_columns(text: str, fmt: str) -> dict[str, int] | None:
    """Колонки заголовка (имя -> индекс), если заголовок подходит к fmt."""
    delimiter, required = _FORMATS[fmt]
    try:
        header = next(_reader(text, delimiter), None)
    except csv.Error:
        return None
    if not header:
        return None
    columns: dict[str, int] = {}
    for idx, name in enumerate(header):
        columns.setdefault(name.strip().casefold(), idx)
    if any(c not in columns for c in required):
        return None
    return {c: columns[c] for c in required}


def _unknown(text: str) -> UnknownFormatError:
    return UnknownFormatError(
        "unrecognized statement header", line_no=1 if text.strip() else None
    )


def _detect(text: str) -> str:
    for fmt in _DETECT_ORDER:
        if _header_columns(text, fmt) is not None:
            return fmt
    raise _unknown(text)


def detect_format(path: str | os.PathLike[str]) -> str:
    """Определяет формат выписки по заголовку."""
    return _detect(_read_text(path)[0])


def _is_junk(row: list[str]) -> bool:
    return all(not cell.strip() for cell in row)


def _parse_sfera_amount(text: str, *, signed: bool) -> Decimal:
    m = _SFERA_AMOUNT.fullmatch(text.strip())
    if m is None:
        raise ValidationError(f"invalid amount: {text!r}")
    sign, whole, frac = m.groups()
    if sign and not signed:
        raise ValidationError(f"unexpected sign in amount: {text!r}")
    digits = re.sub(_SEP, "", whole)
    value = Decimal(f"{digits}.{frac}" if frac else digits)
    if sign == "-":
        value = -value
    return to_money(value)


def _parse_sfera_date(text: str) -> dt.date:
    m = _SFERA_DATE.fullmatch(text.strip())
    if m is None:
        raise ValidationError(f"invalid date {text!r}")
    try:
        return dt.date(int(m.group(3)), int(m.group(2)), int(m.group(1)))
    except ValueError as exc:
        raise ValidationError(f"invalid date {text!r}") from exc


def _build(fmt: str, cols: dict[str, int], row: list[str], imported_at: dt.datetime) -> Transaction:
    """Собирает транзакцию из строки; при любой проблеме бросает ValidationError."""
    if len(row) <= max(cols.values()):
        raise ValidationError("not enough fields")
    cell = {name: row[idx] for name, idx in cols.items()}
    if fmt == "nova":
        try:
            date = dt.date.fromisoformat(cell["date"].strip())
        except ValueError as exc:
            raise ValidationError(f"invalid date {cell['date']!r}") from exc
        amount = parse_amount(cell["amount"])
        description = cell["description"]
    elif fmt == "sfera":
        date = _parse_sfera_date(cell["дата"])
        amount = _parse_sfera_amount(cell["сумма"], signed=True)
        description = cell["описание"]
    else:
        date = _parse_sfera_date(cell["дата"])
        values = {}
        for name in ("приход", "расход"):
            text = cell[name]
            if text.strip():
                values[name] = _parse_sfera_amount(text, signed=False)
            else:
                values[name] = Decimal("0.00")
        filled = [n for n, v in values.items() if v != 0]
        if len(filled) != 1:
            raise ValidationError("exactly one of income/expense must be filled")
        amount = values["приход"] if filled[0] == "приход" else -values["расход"]
        description = cell["описание"]
    return Transaction(
        date=date, amount=amount, description=description.strip(), imported_at=imported_at
    )


def import_statement(
    path: str | os.PathLike[str],
    store: MemoryStore,
    *,
    fmt: str | None = None,
    strict: bool = False,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> ImportResult:
    """Импортирует выписку в store: дедупликация, пропуск мусорных строк, атомарная запись."""
    text, encoding = _read_text(path)
    if fmt is None:
        fmt = _detect(text)
    elif fmt not in _FORMATS:
        raise UnknownFormatError(f"unknown format {fmt!r}")
    cols = _header_columns(text, fmt)
    if cols is None:
        raise _unknown(text)

    clock = clock or SystemClock()
    imported_at = clock.now()
    existing = Counter(
        (tx.date, tx.amount, normalize_description(tx.description)) for tx in store.all()
    )

    new: list[Transaction] = []
    errors: list[RowError] = []
    duplicates = 0
    reader = _reader(text, _FORMATS[fmt][0])
    try:
        next(reader)
        prev = reader.line_num
        for row in reader:
            line_no = prev + 1
            prev = reader.line_num
            if _is_junk(row):
                continue
            try:
                tx = _build(fmt, cols, row, imported_at)
            except ValidationError as exc:
                if strict:
                    raise StatementRowError(str(exc), line_no=line_no) from exc
                errors.append(RowError(line_no, str(exc)))
                continue
            key = (tx.date, tx.amount, normalize_description(tx.description))
            if existing[key] > 0:
                existing[key] -= 1
                duplicates += 1
                continue
            if categorizer is not None:
                category = categorizer.categorize(tx)
                if category is not None:
                    tx = replace(tx, category=category)
            new.append(tx)
    except csv.Error as exc:
        raise StatementError(f"malformed CSV: {exc}", line_no=reader.line_num) from exc

    if new:
        store.add_many(new)
    logger.info(
        "imported %d transactions from %s (%d duplicates, %d errors)",
        len(new), path, duplicates, len(errors),
    )
    return ImportResult(fmt, encoding, len(new), duplicates, errors)


def import_csv(
    path: str | os.PathLike[str],
    store: MemoryStore,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> int:
    """Строгий импорт выписки «Новы»; возвращает число добавленных транзакций."""
    result = import_statement(
        path, store, fmt="nova", strict=True, categorizer=categorizer, clock=clock
    )
    return result.added
